import json
import sys
import os
from pathlib import Path

# Aggiungi la directory padre al path per permettere l'import da qualsiasi directory
backend_dir = Path(__file__).resolve().parent.parent
if str(backend_dir) not in sys.path:
    sys.path.insert(0, str(backend_dir))

from blockchain.config import w3, ACCOUNT
from web3 import Web3

# Determina il percorso del file ABI relativo alla directory di esecuzione
abi_path = Path(__file__).resolve().parent / "abi.json"
if not abi_path.exists():
    abi_path = Path("blockchain/abi.json")

with open(abi_path) as f:
    abi = json.load(f)

bytecode = ""
# Deploy del contratto HealthDataValidator su Quorum RAFT
# Questo script si connette a un nodo Quorum, compila il contratto e lo deploya, specificando i validatori come argomenti o usando gli account disponibili.

# =========================
# CONTRACT FACTORY
# =========================

Contract = w3.eth.contract(abi=abi, bytecode=bytecode)


# =========================
# DEPLOY FUNCTION
# =========================

def deploy_contract(validators):

    print("\n START DEPLOY")

    # checksum + dedup
    validators = [
        Web3.to_checksum_address(v)
        for v in validators
    ]
    validators = list(dict.fromkeys(validators))  # remove duplicates

    print("Validators finali:", validators)

    accounts = w3.eth.accounts
    print("Accounts nodo:", accounts)
    print("Deploying account:", ACCOUNT)

    if ACCOUNT.lower() not in [a.lower() for a in accounts]:
        raise Exception("ACCOUNT non unlocked sul nodo")

    # opzionale: evita doppio inserimento deployer
    if ACCOUNT in validators:
        print("Deployer già nei validators, rimozione duplicato inutile")
    else:
        print("ℹDeployer NON presente nei validators")

    nonce = w3.eth.get_transaction_count(ACCOUNT)

    tx_params = {
        "from": ACCOUNT,
        "nonce": nonce,
        "gas": 10_000_000,
        "gasPrice": w3.eth.gas_price,
    }

    print(" Deploy tx params:", tx_params)

    tx_hash = Contract.constructor(validators).transact(tx_params)

    print("TX sent:", tx_hash.hex())

    receipt = w3.eth.wait_for_transaction_receipt(tx_hash, timeout=120)

    print("\n RECEIPT")
    print("block:", receipt.blockNumber)
    print("gas used:", receipt.gasUsed)
    print("status:", receipt.status)

    if receipt.status != 1:
        raise Exception("Deploy fallito (revert)")

    if not receipt.contractAddress:
        raise Exception("contractAddress mancante")

    address = Web3.to_checksum_address(receipt.contractAddress)

    # salva address
    address_file = Path(__file__).resolve().parent / "address.json"

    with open(address_file, "w") as f:
        json.dump({"address": address}, f)

    print("\nCONTRACT DEPLOYED:", address)

    return address


# =========================
# MAIN
# =========================

if __name__ == "__main__":

    # puoi passare validators da CLI oppure usare default
    if len(sys.argv) > 1:
        validators = sys.argv[1:]
    else:
        validators = [ACCOUNT]

    print("🔧 Validators input:", validators)

    addr = deploy_contract(validators)

    print("\n DONE:", addr)